import React from "react";
import { useNavigate } from "react-router-dom";
import { GoogleLogin } from "@react-oauth/google";
import { jwtDecode } from "jwt-decode";

const Login = () => {
  const navigate = useNavigate();
  // Define event handlers
  const onSuccess = (response) => {
    const idToken = response.credential; // The ID token
    try {
      const decoded = jwtDecode(idToken); // Decode the ID token
      console.log(decoded); // Display user information

      // Store user information or perform further actions
      // For example, you can store the user info in context or state

      // Navigate to the dashboard
      navigate('/dashboard');
    } catch (error) {
      console.error("Failed to decode token", error);
    }
  };


    const onError = () => {
    console.log("Login Failed");
    };

    return (
    <div style={{display:'flex',flexDirection:'column', alignItems: 'center',justifyContent:'center', height:'100%'}}> 
        <h2 style={{color:'white'}}>LOGIN</h2>
        <GoogleLogin onSuccess={onSuccess} onError={onError} />
    </div>
    );
};

export default Login;
